const base=process.env.MOBILE_REVIEW_BASE??'http://localhost:4182';
import {chromium} from '@playwright/test';import fs from 'node:fs';const data=JSON.parse(fs.readFileSync('src/games/game025/mini-fallbacks.json','utf8'));
const b=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox']});const p=await b.newPage({viewport:{width:390,height:844}});await p.addInitScript(()=>localStorage.setItem('game100garage:analytics-consent:v1','denied'));await p.goto(`${base}/game025.html`);await p.locator('#difficulty').selectOption('mini');await p.locator('#board-mode').selectOption('daily');await p.locator('#play').click();const day=await p.evaluate(()=>window.__game025.dailyId);const seed=[...day].reduce((n,c)=>(Math.imul(n,31)+c.charCodeAt(0))>>>0,0),mines=data[seed%data.length].mines;for(let i=0;i<36;i++){if(!mines[i]&&await p.evaluate(i=>!window.__game025.opened[i],i)){await p.locator(`[data-cell="${i}"]`).click();if(await p.evaluate(()=>window.__game025.state)==='result')break;}}
const result=await p.evaluate(()=>({state:window.__game025.state,outcome:window.__game025.outcome,bestTimes:window.__game025.bestTimes,text:document.querySelector('#menu').textContent}));if(result.outcome!=='won'||!result.bestTimes.length||!result.text.includes('この端末 1位'))throw Error(JSON.stringify(result));console.log(JSON.stringify(result));await b.close();
